def reverse_string(s):
  """Reverses a string.  Handles unicode well."""
  return s[::-1]

# Or, for slightly more control, especially useful if you want to reverse in place:
def reverse_string_inplace(s):
  """Reverses a string in place (mutates the original)"""
  return "".join(reversed(s))

# Or, useful if you need a list of characters:
def reverse_string_to_list(s):
  """Reverses a string and returns a list of chars."""
  return list(reversed(s))
